package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertTrue;
import static org.lwjgl.util.lmdb.LMDB.MDB_SUCCESS;
import static org.mockito.Mockito.mockStatic;

import java.io.IOException;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.function.IntConsumer;

import org.lwjgl.PointerBuffer;
import org.lwjgl.util.lmdb.LMDB;
import org.lwjgl.util.lmdb.MDBVal;
import org.mockito.MockedStatic;
import org.mockito.invocation.InvocationOnMock;

/**
 * Observe-only evidence for one successful logical aligned call on its actual native writer thread. Every native
 * operation executes unchanged. The scope deliberately ends before commit/replay; these fixtures exercise batch-local
 * cursor reuse, not transaction lifetime ownership. No legacy database or private field is created or modified.
 */
final class LmdbPersistentMutationBatchObservation implements AutoCloseable {

	private final TripleStore store;
	private final long writer;
	private final Thread writerThread = Thread.currentThread();
	private final int pages;
	private final int metadata;
	private final int deltas;
	private final MockedStatic<LMDB> nativeCalls;
	private final Map<Long, Integer> writerCursors = new HashMap<>();
	private final long[] deltaPuts = new long[4];
	private final List<Integer> callbacks = new ArrayList<>();
	private int delegationDepth;
	private int cursorOpens;
	private int pageCursorOpens;
	private int metadataCursorOpens;
	private long metadataPuts;
	private Thread nativeWriteThread;
	private boolean closed;

	static LmdbPersistentMutationBatchObservation observe(TripleStore store) throws IOException {
		return new LmdbPersistentMutationBatchObservation(store);
	}

	private LmdbPersistentMutationBatchObservation(TripleStore store) throws IOException {
		this.store = store;
		writer = store.writeTxn;
		assertTrue(writer != 0, "observe an already active native writer");
		LmdbPersistentAdjacency adjacency = LmdbPersistentAdjacency.openExisting(writer);
		pages = adjacency.pagesDbi();
		metadata = adjacency.metadataDbi();
		deltas = adjacency.deltasDbi();
		nativeCalls = mockStatic(LMDB.class, this::invoke);
	}

	IntConsumer callbacks(IntConsumer consumer) {
		return index -> {
			assertSame(writerThread, Thread.currentThread(), "callbacks execute on the observed writer thread");
			assertEquals(writer, store.writeTxn, "this observation does not span native writer renewal");
			assertTrue(writerCursors.isEmpty(), "all writer cursors must close before an external callback");
			callbacks.add(index);
			if (consumer != null) {
				consumer.accept(index);
			}
		};
	}

	Thread writerThread() {
		return writerThread;
	}

	List<Integer> callbackIndices() {
		return List.copyOf(callbacks);
	}

	void assertBatch(long added, int distinctPredicates, boolean explicit) {
		assertTrue(closed, "inspect the completed lexical observation, not an open native mock");
		assertTrue(writerCursors.isEmpty());
		int outgoing = explicit ? 0 : 2;
		for (int plane = 0; plane < deltaPuts.length; plane++) {
			assertEquals(plane == outgoing || plane == outgoing + 1 ? added : 0L, deltaPuts[plane],
					"successful actual persistent delta puts for plane " + plane);
		}
		// One lazy batch page cursor and one metadata cursor, plus one short-lived hasPage probe per direction
		// and newly touched predicate. No allowance proportional to the row count can hide per-row cursor churn.
		assertTrue(cursorOpens <= 2 + 2 * distinctPredicates,
				"native cursor opens must be bounded by batch and predicate count, not rows: " + cursorOpens);
		assertTrue(pageCursorOpens <= 1 + 2 * distinctPredicates);
		assertEquals(added > 0 ? 1 : 0, metadataCursorOpens,
				"one metadata cursor serves every successful mutation in the physical batch");
		if (added > 0) {
			assertTrue(pageCursorOpens > 0, "real base-page existence checks must be observed");
			assertTrue(metadataPuts > 0, "real authoritative metadata writes must be observed");
			assertSame(writerThread, nativeWriteThread, "the native seam must run on the actual aligned writer");
		}
	}

	private Object invoke(InvocationOnMock invocation) throws Throwable {
		if (delegationDepth++ != 0) {
			try {
				return invocation.callRealMethod();
			} finally {
				delegationDepth--;
			}
		}
		try {
			String method = invocation.getMethod().getName();
			Object result = invocation.callRealMethod();
			if (method.equals("mdb_cursor_open") && (int) result == MDB_SUCCESS
					&& (long) invocation.getArgument(0) == writer) {
				PointerBuffer handle = invocation.getArgument(2);
				int database = invocation.getArgument(1);
				assertFalse(writerCursors.containsKey(handle.get(0)), "an open native handle cannot be reused");
				writerCursors.put(handle.get(0), database);
				cursorOpens++;
				if (database == pages) {
					pageCursorOpens++;
				}
				if (database == metadata) {
					metadataCursorOpens++;
				}
			} else if (method.equals("mdb_cursor_close")) {
				writerCursors.remove((long) invocation.getArgument(0));
			} else if (method.equals("mdb_put") && (int) result == MDB_SUCCESS
					&& (long) invocation.getArgument(0) == writer && (int) invocation.getArgument(1) == deltas) {
				MDBVal key = invocation.getArgument(2);
				MDBVal value = invocation.getArgument(3);
				assertEquals(33L, key.mv_size(), "observe the real directional edge key");
				assertEquals(1L, value.mv_size());
				assertEquals(1, value.mv_data().get(0), "these fixtures only add absent rows");
				int plane = Byte.toUnsignedInt(key.mv_data().get(0));
				assertTrue(plane < deltaPuts.length);
				deltaPuts[plane]++;
				nativeWriteThread = Thread.currentThread();
			} else if (method.equals("mdb_cursor_put") && (int) result == MDB_SUCCESS
					&& Integer.valueOf(metadata).equals(writerCursors.get((long) invocation.getArgument(0)))) {
				metadataPuts++;
			}
			return result;
		} finally {
			delegationDepth--;
		}
	}

	@Override
	public void close() {
		assertSame(writerThread, Thread.currentThread(), "the static observer remains on its installing thread");
		if (!closed) {
			closed = true;
			try {
				assertTrue(writerCursors.isEmpty(), "all native writer cursors close before aligned return");
			} finally {
				nativeCalls.close();
			}
		}
	}

	static List<List<Long>> rows(long[] subjects, long[] predicates, long[] objects, long[] contexts, int count) {
		List<List<Long>> rows = new ArrayList<>(count);
		for (int index = 0; index < count; index++) {
			rows.add(List.of(subjects[index], predicates[index], objects[index], contexts[index]));
		}
		return rows;
	}

	static void assertDirections(TripleStore store, List<List<Long>> explicit, List<List<Long>> inferred)
			throws IOException {
		try (var txn = store.getTxnManager().createReadTxn()) {
			LmdbPersistentAdjacency adjacency = LmdbPersistentAdjacency.openExisting(txn.get());
			for (boolean isExplicit : new boolean[] { true, false }) {
				for (boolean incoming : new boolean[] { false, true }) {
					String order = incoming ? "posc" : "psoc";
					List<List<Long>> expected = ordered(isExplicit ? explicit : inferred, order);
					try (var iterator = adjacency.scan(txn, -1, -1, -1, -1, isExplicit, incoming)) {
						assertEquals(expected, readRows(iterator),
								"exact persistent " + order + ", explicit=" + isExplicit);
					}
				}
			}
		}
	}

	static void assertOrders(TripleStore store, List<String> orders, List<List<Long>> explicit,
			List<List<Long>> inferred) throws IOException {
		try (var txn = store.getTxnManager().createReadTxn()) {
			for (boolean isExplicit : new boolean[] { true, false }) {
				for (String order : orders) {
					try (var iterator = store.getTriplesRangeUsingIndex(txn, -1, -1, -1, -1, isExplicit,
							new LmdbKeyRange(null, null, order))) {
						assertEquals(ordered(isExplicit ? explicit : inferred, order), readRows(iterator),
								"exact configured full order " + order + ", explicit=" + isExplicit);
					}
				}
			}
		}
	}

	private static List<List<Long>> readRows(RecordIterator iterator) {
		List<List<Long>> result = new ArrayList<>();
		long[] row;
		while ((row = iterator.next()) != null) {
			result.add(List.of(row[0], row[1], row[2], row[3]));
		}
		return result;
	}

	private static List<List<Long>> ordered(List<List<Long>> rows, String order) {
		List<List<Long>> sorted = new ArrayList<>(rows);
		sorted.sort((left, right) -> {
			for (int ordinal = 0; ordinal < order.length(); ordinal++) {
				int field = "spoc".indexOf(order.charAt(ordinal));
				int comparison = Long.compareUnsigned(left.get(field), right.get(field));
				if (comparison != 0) {
					return comparison;
				}
			}
			return 0;
		});
		return sorted;
	}
}
